#include "../cache_model.hpp"
#include <cassert>
#include <iostream>
int main(){using namespace manga;PageCache c;c.budget(1024*1024,false);assert(!c.limit);c.budget(1024*1024,true);assert(!c.limit);c.budget(128ull*1024*1024,true);assert(c.limit==PageCache::maximum);c.pages[0]={"https://source.test/one",262144,1};c.pages[1]={"https://source.test/two",262144,2};c.clock=2;assert(c.oldest()==0);c.touch(0);assert(c.oldest()==1);PageCache restored;assert(restored.restore(c.save()));assert(restored.used()==524288&&restored.find("https://source.test/one")==0);auto stable=restored.save();assert(!restored.restore("{\"version\":1,\"mode\":0,\"pages\":[{\"slot\":99,\"key\":\"https://a.test\",\"bytes\":100}]}"));assert(restored.save()==stable);assert(!restored.restore("{\"version\":1,\"mode\":0,\"pages\":false}"));assert(!restored.restore("{\"version\":1,\"mode\":3,\"pages\":[]}"));std::cout<<"Cache budget, LRU eviction order, persistent index and corrupt-index rejection passed\n";}
